INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Netzwerkdatenbank immer schneller als eine relationale Datenbank ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Anwendung"}, {"text": "Ja", "correct": false, "because": "Zu vereinfacht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich eine Netzwerkdatenbank für ein IT-System einrichte?', 3, '[{"text": "Datenbeziehungen", "correct": true, "because": "Kern der Struktur"}, {"text": "Schnellste Installation", "correct": false, "because": "Struktur zählt"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat eine Netzwerkdatenbank?', 5, '[{"text": "Hierarchische Struktur", "correct": true, "because": "Netzwerkartige Verbindungen"}, {"text": "Mehrere Elternknoten", "correct": true, "because": "Flexible Beziehungen"}, {"text": "Büromöbel", "correct": false, "because": "Kein Merkmal"}, {"text": "Farbanalyse", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Netzwerkdatenbanken unterstützen komplexe Beziehungen. b) Sie sind immer einfacher als relationale Datenbanken.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Komplexer als relational"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine Netzwerkdatenbank für ein IT-System plane?', 4, '[{"text": "Datenhierarchie", "correct": false, "because": "Bestimmt Struktur"}, {"text": "Verbindungen", "correct": false, "because": "Definieren Beziehungen"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Netzwerkdatenbank nur für kleine Datenmengen geeignet ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch große Datenmengen"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Netzwerkdatenbank?', 3, '[{"text": "Flexible Datenbeziehungen", "correct": true, "because": "Netzwerkstruktur"}, {"text": "Schnellste Einrichtung", "correct": false, "because": "Struktur wichtiger"}, {"text": "Weniger Daten", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind bei einer Netzwerkdatenbank entscheidend?', 5, '[{"text": "Knotenverbindungen", "correct": true, "because": "Definieren Beziehungen"}, {"text": "Hierarchische Flexibilität", "correct": true, "because": "Mehrere Eltern"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Netzwerkdatenbanken sind komplexer als hierarchische Modelle. b) Sie sind immer schneller als relationale Datenbanken. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Geschwindigkeit variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um eine Netzwerkdatenbank effektiv einzusetzen?', 4, '[{"text": "Datenmodellierung", "correct": false, "because": "Definiert Struktur"}, {"text": "Verbindungspfade", "correct": false, "because": "Sichern Beziehungen"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
